<script setup>
import {reactive} from 'vue'; import {Head,router} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PageBanner from '../../Components/PageBanner.vue'; defineOptions({layout:AppLayout}); const p=defineProps({shipments:Array,locations:Array}); const forms=reactive({}); const form=s=>forms[s.id]??={vendor_do_number:s.document_no,received_at:new Date().toISOString().slice(0,16),lines:s.lines.map(l=>({refill_line_id:l.refill_line_id,location_id:'',quantity:l.quantity}))};
</script>
<template><Head title="Incoming Refill"/><div class="units-page"><PageBanner title="Incoming Refill" description="Masukkan quantity fisik; posting ini menambah stok Consignment." icon="arrowDown"/><section v-for="s in shipments" :key="s.id" class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="router.post(s.receipt_url,form(s))"><h2>{{s.refill}} · {{s.vendor}}</h2><p>{{s.document_no}} · {{s.status}}</p><input v-model="form(s).vendor_do_number" class="form-input" required/><input v-model="form(s).received_at" class="form-input" type="datetime-local" required/><div v-for="x in form(s).lines" :key="x.refill_line_id" class="form-grid"><div><label>{{s.lines.find(l=>l.refill_line_id===x.refill_line_id)?.item}}</label><input v-model="x.quantity" class="form-input" type="number" min="0.0001" step="0.0001" required/></div><div><label>Lokasi</label><select v-model="x.location_id" class="form-input" required><option value="">Pilih lokasi</option><option v-for="l in locations" :key="l.id" :value="l.id">{{l.location_code}} · {{l.location_name}}</option></select></div></div><button class="button button--primary">Posting penerimaan</button></form></section><section v-if="!shipments.length" class="surface-card"><p class="page-note">Belum ada pengiriman Vendor yang menunggu penerimaan.</p></section></div></template>
